## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/pciLogic.ts`

```typescript
// Elective PCI (Percutaneous Coronary Intervention) Clinical Decision Logic
// Based on: 2021 ACC/AHA/SCAI Guideline for Coronary Artery Revascularization
// Reference: Lawton JS, et al. J Am Coll Cardiol. 2022;79(2):e21-e129. PMID: 34895950

export interface PCIInput {
  // Patient demographics
  age: number;
  sex: 'male' | 'female';
  diabetesMellitus: boolean;

  // Symptom status
  ccsAngina: 0 | 1 | 2 | 3 | 4; // CCS angina class
  dyspnea: boolean;
  silentIschemia: boolean;

  // Anatomy / Imaging
  syntaxScore: number; // SYNTAX score (0–60+)
  numVesselsDisease: 1 | 2 | 3; // number of diseased vessels
  leftMainDisease: boolean;
  proximalLadDisease: boolean;
  chronicTotalOcclusion: boolean;
  lvef: number; // percent

  // Functional assessment
  ffrPositive: boolean; // FFR ≤0.80 or iFR ≤0.89
  stressTestPositive: boolean;
  stressTestHighRisk: boolean; // large ischemic territory ≥10%

  // Medical therapy
  optimalMedicalTherapy: boolean; // on maximal tolerated OMT
  omtDuration: number; // months on OMT

  // Contraindications / comorbidities
  priorCABG: boolean;
  ckdStage: 0 | 1 | 2 | 3 | 4 | 5;
  bleedingRisk: 'low' | 'moderate' | 'high';
  contrastAllergy: boolean;

  // Antiplatelet tolerance
  daptTolerance: boolean; // can tolerate dual antiplatelet therapy
}

export interface PCIResult {
  candidacyScore: number; // 0–100
  recommendation: 'Appropriate' | 'May Be Appropriate' | 'Rarely Appropriate' | 'Insufficient Data';
  appropriatenessRating: string;
  syntaxCategory: 'Low' | 'Intermediate' | 'High';
  preferredStrategy: string;
  keyFindings: string[];
  warnings: string[];
  references: string[];
}

export function calculatePCIScore(input: PCIInput): PCIResult {
  const warnings: string[] = [];
  const keyFindings: string[] = [];
  let score = 0;

  // SYNTAX score categorization
  let syntaxCategory: 'Low' | 'Intermediate' | 'High';
  if (input.syntaxScore <= 22) syntaxCategory = 'Low';
  else if (input.syntaxScore <= 32) syntaxCategory = 'Intermediate';
  else syntaxCategory = 'High';

  // Ischemia burden — primary driver of PCI benefit
  if (input.stressTestHighRisk) {
    score += 30;
    keyFindings.push('High-risk stress test findings (≥10% ischemic territory) — strong indication for revascularization');
  } else if (input.stressTestPositive) {
    score += 15;
    keyFindings.push('Positive stress test with moderate ischemia');
  }

  if (input.ffrPositive) {
    score += 20;
    keyFindings.push('Hemodynamically significant lesion confirmed by FFR ≤0.80 or iFR ≤0.89');
  }

  // Symptom burden
  if (input.ccsAngina >= 3) {
    score += 20;
    keyFindings.push(`Severe angina (CCS Class ${input.ccsAngina}) refractory to medical therapy`);
  } else if (input.ccsAngina >= 1) {
    score += 10;
    keyFindings.push(`Symptomatic angina (CCS Class ${input.ccsAngina})`);
  }

  // OMT adequacy
  if (!input.optimalMedicalTherapy) {
    score -= 15;
    warnings.push('Patient not on optimal medical therapy — OMT trial recommended before elective PCI per ISCHEMIA trial');
  } else if (input.omtDuration >= 3) {
    keyFindings.push(`Symptoms persist despite ${input.omtDuration} months of optimal medical therapy`);
  }

  // Anatomy considerations
  if (input.leftMainDisease) {
    if (syntaxCategory === 'Low' || syntaxCategory === 'Intermediate') {
      score += 15;
      keyFindings.push('Left main disease — PCI appropriate for low/intermediate SYNTAX score (Class IIa)');
    } else {
      warnings.push('Left main disease with high SYNTAX score — CABG preferred (Class I)');
      score -= 10;
    }
  }

  if (input.proximalLadDisease) {
    score += 10;
    keyFindings.push('Proximal LAD disease — revascularization associated with mortality benefit');
  }

  if (input.numVesselsDisease === 3 && syntaxCategory === 'High') {
    warnings.push('3-vessel disease with high SYNTAX score — CABG preferred over PCI (Class I)');
    score -= 15;
  } else if (input.numVesselsDisease === 3 && syntaxCategory === 'Intermediate') {
    warnings.push('3-vessel disease with intermediate SYNTAX score — Heart Team discussion recommended');
    score -= 5;
  }

  if (input.chronicTotalOcclusion) {
    keyFindings.push('Chronic total occlusion present — complex PCI; operator experience critical');
  }

  // LVEF
  if (input.lvef < 35) {
    warnings.push('Severely reduced LVEF (<35%) — consider hemodynamic support and Heart Team evaluation');
  } else if (input.lvef < 50) {
    keyFindings.push(`Reduced LVEF (${input.lvef}%) — revascularization may improve function if viable myocardium present`);
    score += 5;
  }

  // DAPT tolerance — critical for PCI
  if (!input.daptTolerance) {
    warnings.push('Unable to tolerate DAPT — high stent thrombosis risk; consider CABG or medical therapy');
    score -= 20;
  }

  // Bleeding risk
  if (input.bleedingRisk === 'high') {
    warnings.push('High bleeding risk — consider bare-metal stent or short DAPT duration strategy');
    score -= 5;
  }

  // CKD
  if (input.ckdStage >= 4) {
    warnings.push('Advanced CKD (Stage ≥4) — contrast nephropathy risk; pre-hydration and iso-osmolar contrast required');
  }

  // Prior CABG
  if (input.priorCABG) {
    keyFindings.push('Prior CABG — native vessel PCI or SVG intervention; higher risk of no-reflow');
  }

  // Clamp score
  score = Math.max(0, Math.min(100, score));

  // Determine recommendation
  let recommendation: PCIResult['recommendation'];
  let appropriatenessRating: string;
  let preferredStrategy: string;

  if (score >= 60) {
    recommendation = 'Appropriate';
    appropriatenessRating = 'Score 7–9: Elective PCI is appropriate based on clinical and anatomical criteria';
    preferredStrategy = input.numVesselsDisease === 1 || syntaxCategory === 'Low'
      ? 'Single-vessel or low-complexity PCI with drug-eluting stent (DES)'
      : 'Heart Team discussion; PCI feasible for low/intermediate SYNTAX anatomy';
  } else if (score >= 35) {
    recommendation = 'May Be Appropriate';
    appropriatenessRating = 'Score 4–6: Elective PCI may be appropriate; individualized decision required';
    preferredStrategy = 'Heart Team evaluation recommended; consider ISCHEMIA trial data for stable CAD';
  } else {
    recommendation = 'Rarely Appropriate';
    appropriatenessRating = 'Score 1–3: Elective PCI is rarely appropriate in this clinical scenario';
    preferredStrategy = 'Optimize medical therapy; reassess symptoms at 3–6 months; consider CABG if anatomy favors';
  }

  return {
    candidacyScore: score,
    recommendation,
    appropriatenessRating,
    syntaxCategory,
    preferredStrategy,
    keyFindings,
    warnings,
    references: [
      'Lawton JS, et al. 2021 ACC/AHA/SCAI Guideline for Coronary Artery Revascularization. J Am Coll Cardiol. 2022;79(2):e21-e129. PMID: 34895950',
      'Maron DJ, et al. ISCHEMIA Trial. Initial Invasive or Conservative Strategy for Stable Coronary Disease. N Engl J Med. 2020;382(15):1395-1407. PMID: 32227755',
      'Farooq V, et al. SYNTAX Score II. Lancet. 2013;381(9867):639-650. PMID: 23439103',
      'Neumann FJ, et al. 2018 ESC/EACTS Guidelines on Myocardial Revascularization. Eur Heart J. 2019;40(2):87-165. PMID: 30165437',
      'Pijls NH, et al. FAME Trial. Fractional Flow Reserve vs Angiography. N Engl J Med. 2009;360(3):213-224. PMID: 19144937',
    ],
  };
}
